 "content": "from collections import deque


def transform(grid):
    """Color every fully surrounded interior pixel with its component's marker color."""
    h, w = len(grid), len(grid[0])
    labels = [[-1] * w for _ in range(h)]
    component_colors = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or labels[r][c] != -1:
                continue
            label = len(component_colors)
            q = deque([(r, c)])
            labels[r][c] = label
            colors = set()
            while q:
                y, x = q.popleft()
                if grid[y][x] not in (0, 1):
                    colors.add(grid[y][x])
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and labels[ny][nx] == -1:
                        labels[ny][nx] = label
                        q.append((ny, nx))
            component_colors.append(colors)

    out = [row[:] for row in grid]
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] != 1:
                continue
            label = labels[r][c]
            colors = component_colors[label]
            if len(colors) != 1:
                continue
            if all(grid[r + dy][c + dx] != 0
                   for dy in (-1, 0, 1) for dx in (-1, 0, 1)):
                out[r][c] = next(iter(colors))
    return out


if __name__ == '__main__':
    pass
